using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GlowingReactorOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/GlowingReactor Omen Data")]
public class GlowingReactorOmenData : OnStartOfBattleOmenData
{
	[Header("Glowing Reactor")]
	[SerializeField]
	private int barrierLightShieldAmount;

	[SerializeField]
	private int incorruptibleLightShieldAmount;

	public override void Initialize(OmenInstance omenInstance)
	{
		Action glowingReactorOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorOmenAction = glowingReactorOmenAction;
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorBarrierLightShieldOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			OmenLogic.ActivateOmen(BattleAction, barrierLightShieldAmount, null, null);
		};
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorIncorruptibleLightShieldOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			OmenLogic.ActivateOmen(BattleAction, incorruptibleLightShieldAmount, null, null);
		};
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorOmenAction = null;
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorIncorruptibleLightShieldOmenAction = null;
		ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorBarrierLightShieldOmenAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		string startOfBattleLocalizedDescription = GetStartOfBattleLocalizedDescription();
		return Smart.Format(GetOmenRawLocalizedDescription(), BattleAction.GetActionDescription(barrierLightShieldAmount).LowercaseFirst(), BattleAction.GetActionDescription(incorruptibleLightShieldAmount).LowercaseFirst()) + "\n" + startOfBattleLocalizedDescription + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetOmenConvertedDescriptionBattleAction().LowercaseFirst();
	}
}
